from PIL import Image, ImageEnhance
import numpy as np
from io import BytesIO
import re

def removedor_fundo_inteligente(img, threshold):
    """
    Remove o fundo baseado na luminosidade.
    Pixels muito claros (brancos/fundos) ficam com brilho (Alpha) 0.
    """
    img = img.convert("RGBA")
    data = np.array(img)
    
    # Pega os canais RGB
    rgb = data[:,:,:3]
    # Calcula luminosidade aproximada
    luminosidade = np.mean(rgb, axis=2)
    
    # Onde a luminosidade for maior que o threshold, zeramos o Alpha (Transparente/Apagado)
    # Onde for menor (imagem), deixamos o Alpha em 255
    data[:,:,3] = np.where(luminosidade > threshold, 10, 255)
    
    return Image.fromarray(data)

def gerar_matriz_polar(img, num_setores=40, led_count=36):
    """
    Mapeia a imagem para coordenadas polares.
    O centro da imagem vira o eixo do motor.
    """
    
    img = img.convert("RGBA")
    img = img.resize((num_setores, led_count), Image.LANCZOS)  # LANCZOS para melhor qualidade
    #img.show()  # Para verificar como a imagem ficou após o redimensionamento

    largura, altura = img.size
    #print(f"Imagem carregada: {largura}x{altura}")
    centro_x = largura / 2
    centro_y = altura / 2
    
    # O raio máximo que podemos pegar é metade da menor dimensão da imagem
    raio_max = min(centro_x, centro_y)
    
    array_saida = []
    array_pixels = np.array(img)

    for y, linha in enumerate(array_pixels):
        for x, pixel in enumerate(linha):
            #print(f"Posição: x={x}, y={y}, pixel={pixel}")  # Debug: mostra o valor do pixel

            led = img.getpixel((x, y))
            r, g, b, a = led
            #print(f"Pixel: R={r}, G={g}, B={b}, A={a}")

            array_saida.append(f"{{{r},{g},{b},{a}}}")

    '''
    print(f"Total de pixels processados: {len(array_saida)}")
    print(f"Formato final: {num_setores} setores x {led_count} LEDs = {num_setores*led_count} pixels.")
    print("Exemplo de saída (primeiros 10 pixels):")
    print(array_saida[:10])
    '''
            
    return array_saida

